                radiusMeters: double(from: stateValue(for: "searchRadiusMetersText")) ?? 1000
            )
            mergeState([
                "lastSearch": .object([
                    "status": .string("ok"),
                    "results": .list(results.map { .object($0) }),
                    "resultCount": .integer(results.count),
                    "summary": .string(results.isEmpty
                        ? "No signals nearby. Be the first - publish yours."
                        : "\(results.count) active nearby signal(s), ranked by expiry, radius and purpose/interest overlap."),
                    "emptyStateTitle": .string("No signals nearby"),
                    "emptyStateMessage": .string("Be the first - publish yours"),
                    "deniedLocationMessage": .string("Location access denied. Enable in settings or enter manually."),
                    "unavailableMessage": .string("This signal is no longer available.")
                ]),
                "selectedSignal": results.first.map(ValueType.object) ?? .object([:]),
                "lastAction": .string("searchNearbySignals")
            ])
            await refreshModerationCounts()
            return response(status: "ok", message: "Nearby signal search refreshed.")
        case "signalDetail":
            guard let signal = await NearbySignalLocalStore.shared.signalDetail(signalID: requestedSignalID(from: value)) else {
                return response(status: "notFound", message: "No active nearby signal detail is available.")
            }
            setStateValue(.object(signal), for: "selectedSignal")
            return response(status: "ok", message: "Nearby signal detail loaded.")
        case "reportSignal":
            guard let signal = await NearbySignalLocalStore.shared.reportSignal(signalID: requestedSignalID(from: value)) else {
                return response(status: "notFound", message: "No active nearby signal to report.")
            }
            setStateValue(.object(signal), for: "selectedSignal")
            await refreshModerationCounts()
            return response(status: "ok", message: "Nearby signal reported for moderation.")
        case "hideSignal":
            guard let signal = await NearbySignalLocalStore.shared.hideSignal(signalID: requestedSignalID(from: value)) else {
                return response(status: "notFound", message: "No active nearby signal to hide.")
            }
            setStateValue(.object(signal), for: "selectedSignal")
            await refreshModerationCounts()
            return response(status: "ok", message: "Nearby signal hidden for this requester.")
        case "blockPublisher":
            guard let signal = await NearbySignalLocalStore.shared.blockPublisher(signalID: requestedSignalID(from: value)) else {
                return response(status: "notFound", message: "No publisher to block.")
            }
            setStateValue(.object(signal), for: "selectedSignal")
            await refreshModerationCounts()
            return response(status: "ok", message: "Nearby signal publisher blocked for this requester.")
        default:
            return await super.handleSet(key: key, value: value)
        }
    }

    private func refreshModerationCounts() async {
        let state = await NearbySignalLocalStore.shared.moderationState()
        for (key, value) in state {
            setStateValue(value, for: key)
        }
    }

    private func normalizedRefs(from value: ValueType?) -> [String] {
        guard case let .string(text)? = value else { return [] }
        return text.split(separator: ",").map { item in
            item.trimmingCharacters(in: .whitespacesAndNewlines)
        }.filter { !$0.isEmpty }
    }

    private func requestedSignalID(from value: ValueType) -> String? {
        if case let .string(signalID) = value {
            return signalID.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? nil : signalID
        }
        if case let .object(object) = value,
           case let .string(signalID)? = object["signalID"] {
            let trimmed = signalID.trimmingCharacters(in: .whitespacesAndNewlines)
            return trimmed.isEmpty ? nil : trimmed
        }
        if case let .object(selected)? = stateValue(for: "selectedSignal"),
           case let .string(signalID)? = selected["signalID"] {
            let trimmed = signalID.trimmingCharacters(in: .whitespacesAndNewlines)
            return trimmed.isEmpty ? nil : trimmed
        }
        return nil
    }

    private func double(from value: ValueType?) -> Double? {
        switch value {
        case let .float(number):
            return number
        case let .integer(number):
            return Double(number)
        case let .string(text):
            return Double(text.trimmingCharacters(in: .whitespacesAndNewlines))
        default:
            return nil
        }
    }
}

private final class PersonalChatClientLocalCell: PersonalCopilotLocalCell {
    required init(owner: Identity) async {
        await super.init(owner: owner)
    }

    nonisolated required init(from decoder: Decoder) throws {
        try super.init(from: decoder)
    }

    override var readableKeys: [String] {
        ["state", "compose.body", "compose.contentType", "blockedUsers", "moderationStatus"]
    }

    override var writableKeys: [String] {
        [
            "invite",
            "acceptInvite",
            "declineInvite",
            "compose.body",
            "compose.contentType",
            "sendComposedMessage",
            "clearComposer",
            "reportMessage",
            "blockUser"
        ]
    }

    nonisolated override func initialState() -> Object {
        [
            "inviteStatus": .string("not invited"),
            "moderationStatus": .string("ready: filtering, report and block controls are visible"),
            "filteringStatus": .string("client-side safety gate active"),
            "blockedUsers": .list([]),
            "blockedUsersSummary": .string("No blocked users"),
            "compose": .object([
                "body": .string(""),
                "contentType": .string("text/plain")
            ]),
            "messages": .list([]),
            "messageCount": .integer(0),
            "meetingBridge": .object([
                "provider": .string("jitsi"),
                "joinURL": .string("disabled in v1"),
                "roomName": .string(""),
                "scheduledAt": .string(""),
                "requiresCameraMicrophoneConsent": .string("true - Binding does not request camera or microphone in v1")
            ]),
            "status": .string("Invite-only chat client is ready."),
            "updatedAt": .float(Date().timeIntervalSince1970)
        ]
    }

    override func handleSet(key: String, value: ValueType) async -> ValueType {
        switch key {
        case "invite":
            mergeState([
                "inviteStatus": .string("invite pending explicit acceptance"),
                "lastAction": .string("invite")
            ])
            return response(status: "ok", message: "Invite staged. Chat will not start until accepted.")
        case "acceptInvite":
            mergeState([
                "inviteStatus": .string("accepted"),
                "lastAction": .string("acceptInvite")
            ])
            return response(status: "ok", message: "Invite accepted locally.")
        case "declineInvite":
            mergeState([
                "inviteStatus": .string("declined"),
                "lastAction": .string("declineInvite")
            ])
            return response(status: "ok", message: "Invite declined locally.")
        case "compose.body":
            setStateValue(value, for: "compose.body")
            return response(status: "ok", message: "Composer draft updated locally.")
        case "compose.contentType":
            setStateValue(value, for: "compose.contentType")
            return response(status: "ok", message: "Composer content type updated.")
        case "sendComposedMessage":
            return sendComposedMessage()
        case "clearComposer":
            setStateValue(.string(""), for: "compose.body")
            return response(status: "ok", message: "Composer cleared.")
        case "reportMessage":
            mergeState([
                "moderationStatus": .string("latest visible message reported for review"),
                "lastAction": .string("reportMessage")
            ])
            return response(status: "ok", message: "Report recorded locally and ready for PersonalChatHub.")
        case "blockUser":
            mergeState([
                "blockedUsers": .list([.string("blocked-user")]),
                "blockedUsersSummary": .string("1 blocked user"),
                "moderationStatus": .string("blocked user cannot continue this conversation"),
                "inviteStatus": .string("blocked"),
                "lastAction": .string("blockUser")
            ])
            return response(status: "ok", message: "User blocked. Local send flow is disabled.")
        default:
            return await super.handleSet(key: key, value: value)
        }
    }

    private func sendComposedMessage() -> ValueType {
        guard case let .string(inviteStatus)? = stateValue(for: "inviteStatus"),
              inviteStatus == "accepted"
        else {
            return response(status: "blocked", message: "Invite must be accepted before sending.")
        }

        if case let .list(blocked)? = stateValue(for: "blockedUsers"), !blocked.isEmpty {
            return response(status: "blocked", message: "Message not sent because a participant is blocked.")
        }

        let body = stringValue(stateValue(for: "compose.body") ?? .string(""))
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !body.isEmpty else {
            return response(status: "blocked", message: "Write a message before sending.")
        }

        let contentType = stringValue(stateValue(for: "compose.contentType") ?? .string("text/plain"))
        let timestamp = Date().timeIntervalSince1970
        var messages: [ValueType] = []
        if case let .list(existing)? = stateValue(for: "messages") {
            messages = existing
        }
        messages.append(.object([
            "id": .string(UUID().uuidString),
            "sender": .string("local-requester"),
            "body": .string(body),
            "contentType": .string(contentType),
            "sentAt": .float(timestamp),
            "delivery": .string("local-pending-hub-sync")
        ]))
        mergeState([
            "messages": .list(messages),
            "messageCount": .integer(messages.count),
            "compose": .object([
                "body": .string(""),
                "contentType": .string(contentType)
            ]),
            "lastAction": .string("sendComposedMessage")
        ])
        return response(status: "ok", message: "Message added locally and ready for hub sync.")
    }
}

