            "hiddenNearby": .list(hiddenNearbyCards.map(ValueType.object)),
            "allNearby": .list(allNearbyCards.map(ValueType.object)),
            "emptyState": .string(primaryVisibleEntities.isEmpty ? "No relevant entities nearby." : ""),
