        return .object([
            "title": .string(title),
            "subtitle": .string(cardSubtitle(from: raw)),
            "detail": .string(cardDetail(from: raw)),
            "note": .string(updatedNote),
            "keypath": .string("chatSnapshot.dispatchAction"),
