+        guard FileManager.default.fileExists(atPath: directoryURL.path, isDirectory: &isDirectory),
+              isDirectory.boolValue else {
+            if required {
+                throw ConfigurationSourceError.requiredDirectoryMissing
+            }
+            return ConfigurationLoadReport(discovered: 0, loaded: 0, failed: 0)
