+            .filter { $0.lowercased().hasSuffix(".json") }
+            .sorted()
+        if fileList.isEmpty, required {
+            throw ConfigurationSourceError.requiredDirectoryEmpty
+        }
+
+        var decodedConfigurations = [CellConfiguration]()
+        var failedFiles = [String]()
+        for currentTemplateName in fileList {
+            do {
+                let templateURL = directoryURL.appendingPathComponent(currentTemplateName)
+                let jsonData = try Data(contentsOf: templateURL)
+                decodedConfigurations.append(
+                    try JSONDecoder().decode(CellConfiguration.self, from: jsonData)
+                )
+            } catch {
+                failedFiles.append(currentTemplateName)
