+            CellBase.diagnosticLog(
+                "Loaded \(decodedConfigurations.count) Cell configurations; \(failedFiles.count) invalid files were skipped",
+                domain: .lifecycle
+            )
+        }
+        return ConfigurationLoadReport(
+            discovered: fileList.count,
+            loaded: decodedConfigurations.count,
+            failed: failedFiles.count
+        )
     }


