// SPDX-License-Identifier: Apache-2.0
// SPDX-FileCopyrightText: Copyright (c) 2026 Stiftelsen Digipomps and HAVEN contributors

@preconcurrency import CellBase
import Foundation
import Vapor

/// Public, fixed-action projection of the house's corpus. HTTP input never
/// selects a principal, cell endpoint, keypath, audience or resolver policy.
struct PalazzoCommunaleFacade: RouteCollection {
    static let schema = "haven.palazzo.communale.guest-concierge.v1"
    static let configurationName = "Palazzo Communale Concierge"
    static let maximumBodyBytes = 4_096
    private let activity = PalazzoCommunaleActivity()
    private let limiter = PalazzoCommunaleRateLimiter()
    private let endpoint = PalazzoScaffoldContract.Cells.endpoint(PalazzoScaffoldContract.Cells.conciergeCorpus)

    private struct AskRequest: Content { let query: String }

    func boot(routes: RoutesBuilder) throws {
        // Separate from the /api routes: only this narrow facade is public.
        // The generic routes still call PalazzoPrincipalGateway.requester(req).
        let surface = routes.grouped("palazzo").grouped(PalazzoCommunaleSurfaceMiddleware())
        surface.get { req async throws -> Response in
            try await req.fileio.asyncStreamFile(at: req.application.directory.publicDirectory + "palazzo/index.html")
        }
        let api = surface.grouped("api")
        api.get("configuration") { _ async throws -> Response in
            // Web configuration; this scaffold does not host Porthole.
            try Self.json(.object([
                "schema": .string(Self.schema),
                "configurationName": .string(Self.configurationName),
                "apiBase": .string("/palazzo/api"),
                "surface": .string("/palazzo"),
                "actions": palazzoStringListValue(["ask", "menu", "beverages"])
            ]))
        }
        api.get("state") { _ async throws -> Response in
            let corpus = try await corpusState()
            return try Self.json(.object(await activity.state(corpus: corpus)))
        }

        let actions = api.grouped(PalazzoCommunaleRequestMiddleware(limiter: limiter))
        actions.on(.POST, "ask", body: .collect(maxSize: "4kb")) { req async throws -> Response in
            let input: AskRequest
            do { input = try req.content.decode(AskRequest.self) }
            catch { throw Abort(.badRequest, reason: "Send et JSON-objekt med spørsmålet i feltet query.") }
            let query = input.query.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !query.isEmpty else {
                throw Abort(.unprocessableEntity, reason: "Skriv et spørsmål før du sender.")
            }
            guard query.count <= 1_200 else {
                throw Abort(.payloadTooLarge, reason: "Spørsmålet kan være maksimalt 1200 tegn.")
            }
            return try await perform("ask", keypath: PalazzoScaffoldContract.Concierge.query,
                                     payload: .object(["query": .string(query), "audience": .string("guest")]))
        }
        for (path, keypath) in [("menu", PalazzoScaffoldContract.Concierge.menuCurrent),
                                ("beverages", PalazzoScaffoldContract.Concierge.beverageCurrent)] {
            actions.on(.POST, .constant(path), body: .collect(maxSize: "4kb")) { _ async throws -> Response in
                try await perform(path, keypath: keypath, payload: .object(["audience": .string("guest")]))
            }
        }
    }

    private func corpusState() async throws -> Object {
        // Same house principal as the existing concierge behaviour tests.
        // Resolver admission and the cell's owner/consent checks still run.
        let house = try await PalazzoPrincipalGateway.houseIdentity()
        let state = try await PalazzoCellAccess.get(endpoint, keypath: PalazzoScaffoldContract.Concierge.state, requester: house)
        try Self.checkDenial(state)
        return palazzoObjectValue(state)
    }

    private func perform(_ operation: String, keypath: String, payload: ValueType) async throws -> Response {
        let corpus = try await corpusState()
        guard palazzoTrimmedString(corpus["corpusStatus"]) == "bundled" else {
            return try Self.json(.object(PalazzoCommunaleProjection.unavailable()), status: .serviceUnavailable)
        }
        let house = try await PalazzoPrincipalGateway.houseIdentity()
        let value = try await PalazzoCellAccess.set(endpoint, keypath: keypath, value: payload, requester: house)
        try Self.checkDenial(value)
        let answer = PalazzoCommunaleProjection.project(value)
        await activity.record(operation: operation, answer: answer)
        return try Self.json(.object(answer))
    }

    private static func checkDenial(_ value: ValueType) throws {
        if palazzoTrimmedString(palazzoObjectValue(value)["status"]) == "denied" {
            throw Abort(.forbidden, reason: "Tilgang til kunnskapsgrunnlaget ble avvist.")
        }
    }

    static func json(_ value: ValueType, status: HTTPResponseStatus = .ok) throws -> Response {
        Response(status: status, headers: ["Content-Type": "application/json; charset=utf-8"],
                 body: .init(string: try value.jsonString()))
    }
}

/// No query, answer, requester identity or corpus records are retained here.
private actor PalazzoCommunaleActivity {
    private var responseCount = 0
    private var lastOperation = "none"
    private var lastConfidence = "not-checked"
    private var lastNeedsHumanReview = false

    func record(operation: String, answer: Object) {
        responseCount += 1
        lastOperation = operation
        lastConfidence = palazzoTrimmedString(answer["confidence"]) ?? "blocked"
        lastNeedsHumanReview = answer["needs_human_review"] == .bool(true)
    }

    func state(corpus: Object) -> Object {
        let loaded = palazzoTrimmedString(corpus["corpusStatus"]) == "bundled"
        let scope = palazzoObjectValue(corpus["guestReadyScope"])
        let date = PalazzoCommunaleProjection.verifiedDate(scope["last_verified"])
        let message = loaded
            ? "Concierge bruker et datert kunnskapsgrunnlag, sist verifisert \(date ?? "på ukjent dato"). Dagens meny, priser og tilgjengelighet må bekreftes av Palazzo."
            : "Kunnskapsgrunnlaget kunne ikke lastes. Kontakt Palazzo direkte."
        return [
            "schema": .string(PalazzoCommunaleFacade.schema),
            "remoteMode": .string("PalazzoConciergeCorpus (native)"),
            "serviceStatus": .string(loaded ? "limited" : "unavailable"),
            "serviceMessage": .string(message),
            "remoteReadinessScope": .string(loaded ? "dated-corpus" : "unavailable"),
            "responseCount": .integer(responseCount),
            "lastOperation": .string(lastOperation),
            "lastConfidence": .string(lastConfidence),
            "lastNeedsHumanReview": .bool(lastNeedsHumanReview),
            "retention": .string("Spørsmål og svar lagres ikke av Palazzo Communale-fasaden. Kunnskapscellen fører en handlingsteller og sender svar som hendelser i den lokale kjøretiden."),
            "privacyBoundary": .string("Bare spørsmål, meny og drikke sendes til husets kunnskapscelle. Gjesteidentitet, administrasjon og private opplysninger er ikke tilgjengelige gjennom fasaden."),
            "safetySummary": .string("Usikre svar stoppes. Alvorlig allergi, krysskontakt og endringer i menyen må bekreftes av personalet.")
        ]
    }
}

actor PalazzoCommunaleRateLimiter {
    private struct Window { var count: Int; let expires: Date }
    private var windows: [String: Window] = [:]

    func recordAttempt(client: String, now: Date = Date()) -> Int? {
        windows = windows.filter { $0.value.expires > now }
        var window = windows[client] ?? Window(count: 0, expires: now.addingTimeInterval(600))
        guard window.count < 30 else { return max(1, Int(ceil(window.expires.timeIntervalSince(now)))) }
        window.count += 1
        windows[client] = window
        return nil
    }

    static func clientAddress(_ request: Request) -> String {
        // nginx must REPLACE untrusted X-Forwarded-For at the public ingress.
        // First value preserves the guest IP through the proxy chain; without
        // it all guests behind nginx would share one 30-attempt allowance.
        if let first = request.headers.first(name: "X-Forwarded-For")?
            .split(separator: ",", omittingEmptySubsequences: false).first?
            .trimmingCharacters(in: .whitespacesAndNewlines), !first.isEmpty {
            return first
        }
        return request.remoteAddress?.ipAddress ?? "unknown"
    }
}

private struct PalazzoCommunaleRequestMiddleware: AsyncMiddleware {
    let limiter: PalazzoCommunaleRateLimiter

    func respond(to request: Request, chainingTo next: AsyncResponder) async throws -> Response {
        // Count attempts before decoding/collecting, including invalid requests.
        if let retry = await limiter.recordAttempt(client: PalazzoCommunaleRateLimiter.clientAddress(request)) {
            throw Abort(.tooManyRequests, headers: ["Retry-After": "\(retry)"],
                        reason: "For mange forespørsler. Prøv igjen om \(retry) sekunder.")
        }
        if let length = request.headers.first(name: .contentLength).flatMap(Int.init),
           length > PalazzoCommunaleFacade.maximumBodyBytes {
            throw Abort(.payloadTooLarge, reason: "Forespørselen er for stor.")
        }
        // Also enforce the bound for already-collected in-process requests.
        if let size = request.body.data?.readableBytes, size > PalazzoCommunaleFacade.maximumBodyBytes {
            throw Abort(.payloadTooLarge, reason: "Forespørselen er for stor.")
        }
        if request.url.path.hasSuffix("/ask") || request.headers.contentType != nil {
            guard request.headers.contentType?.type == "application",
                  request.headers.contentType?.subType == "json" else {
                throw Abort(.unsupportedMediaType, reason: "Bruk application/json.")
            }
        }
        return try await next.respond(to: request)
    }
}

private struct PalazzoCommunaleSurfaceMiddleware: AsyncMiddleware {
    func respond(to request: Request, chainingTo next: AsyncResponder) async throws -> Response {
        let response: Response
        do {
            response = try await next.respond(to: request)
        } catch CellAuthorizationError.denied {
            response = try errorResponse(.forbidden, "Tilgang til kunnskapsgrunnlaget ble avvist.")
        } catch CellSetupError.ownerAuthorityUnavailable {
            response = try errorResponse(.forbidden, "Tilgang til kunnskapsgrunnlaget ble avvist.")
        } catch let abort as any AbortError {
            // Framework errors can be English or include internal details.
            let reason: String
            switch abort.status {
            case .payloadTooLarge: reason = "Forespørselen er for stor. Bruk maksimalt 4096 byte og 1200 tegn i spørsmålet."
            case .unsupportedMediaType: reason = "Bruk application/json."
            case .unprocessableEntity: reason = "Skriv et spørsmål før du sender."
            case .tooManyRequests: reason = "For mange forespørsler. Vent før du prøver igjen."
            case .forbidden, .unauthorized: reason = "Tilgang til kunnskapsgrunnlaget ble avvist."
            case .badRequest: reason = "Ugyldig forespørsel. Send et JSON-objekt med spørsmålet i feltet query."
            default: reason = "Palazzo Communale er midlertidig utilgjengelig."
            }
            response = try errorResponse(abort.status, reason)
            if let retry = abort.headers.first(name: "Retry-After") {
                response.headers.replaceOrAdd(name: "Retry-After", value: retry)
            }
        } catch {
            request.logger.error("Palazzo Communale native request failed (no request content logged).")
            response = try PalazzoCommunaleFacade.json(.object(PalazzoCommunaleProjection.unavailable()), status: .serviceUnavailable)
        }
        response.headers.replaceOrAdd(name: .cacheControl, value: "no-store")
        response.headers.replaceOrAdd(name: "Content-Security-Policy", value: "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'")
        response.headers.replaceOrAdd(name: "X-Content-Type-Options", value: "nosniff")
        response.headers.replaceOrAdd(name: "Referrer-Policy", value: "no-referrer")
        response.headers.replaceOrAdd(name: "Permissions-Policy", value: "camera=(), microphone=(), geolocation=(), payment=()")
        response.headers.replaceOrAdd(name: "Cross-Origin-Opener-Policy", value: "same-origin")
        return response
    }

    private func errorResponse(_ status: HTTPResponseStatus, _ reason: String) throws -> Response {
        try PalazzoCommunaleFacade.json(.object(["error": .bool(true), "reason": .string(reason)]), status: status)
    }
}
